INSERT INTO `courses` (`id`, `name`, `course_benefits`, `created_at`, `updated_at`) VALUES
(1, 'A1', '<p><strong><span style=\"font-size:22px\">Course Outcomes:&nbsp;</span></strong></p>\r\n\r\n<p><strong><span style=\"font-size:16px\">After finishing this level, students will be able to:</span></strong></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">use simple words and phrases for talking with others.</span></li>\r\n	<li><span style=\"font-size:16px\">introduce themselves and chat about common things using everyday words.</span></li>\r\n	<li><span style=\"font-size:16px\">understand and use basic grammar rules and patterns.</span></li>\r\n	<li><span style=\"font-size:16px\">read simple texts and write easy sentences.</span></li>\r\n	<li><span style=\"font-size:16px\">find the main points and details in sentences with simple words and structure.</span></li>\r\n</ul>\r\n\r\n<p><strong><span style=\"font-size:22px\">Course description</span></strong></p>\r\n\r\n<p><span style=\"font-size:16px\"><span style=\"font-size:16px\"><strong>Skills Covered:</strong></span></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\"><span style=\"font-size:16px\">Reading, Writing</span></span></li>\r\n	<li><span style=\"font-size:16px\"><span style=\"font-size:16px\">Listening, Speaking</span></span></li>\r\n	<li><span style=\"font-size:16px\"><span style=\"font-size:16px\">Grammar and Vocabulary</span></span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\"><span style=\"font-size:16px\"><strong>On-campus class:</strong></span></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">A1 Student Book- 36 hours (Total 24 Classes)</span></li>\r\n	<li><span style=\"font-size:16px\">Language Club- 6 hours</span></li>\r\n	<li><span style=\"font-size:16px\">Assessments- 3 hours</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\"><span style=\"font-size:16px\"><strong>Online class:</strong></span></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">A1 Student Book (Listening)- 6 hours</span></li>\r\n	<li><span style=\"font-size:16px\">Total Class and Assessments - 45 hours</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\"><span style=\"font-size:16px\"><strong>Homework &amp; Assignments:</strong></span></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\"><span style=\"font-size:16px\">HW from Work Book- 60 hours</span></span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\"><span style=\"font-size:16px\"><strong>Assessment Process:</strong></span></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\"><span style=\"font-size:16px\">Pre-Course test-1</span></span></li>\r\n	<li><span style=\"font-size:16px\"><span style=\"font-size:16px\">Class test- 12</span></span></li>\r\n	<li><span style=\"font-size:16px\"><span style=\"font-size:16px\">Mid-term progress test- 1</span></span></li>\r\n	<li><span style=\"font-size:16px\"><span style=\"font-size:16px\">Promotion test (full-length IELTS mock exam)- 1</span></span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\"><span style=\"font-size:16px\"><strong>Study materials</strong></span></span></p>\r\n\r\n<ol>\r\n	<li><span style=\"font-size:16px\">A1 Skill Builder- Student Book</span></li>\r\n	<li><span style=\"font-size:16px\">A1 Skill Builder- Work Book</span></li>\r\n	<li><span style=\"font-size:16px\">Vocabulary Dairy</span></li>\r\n</ol>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:20px\"><strong>Total Duration of Guided Study:&nbsp;&nbsp;100 hours</strong></span></p>', '2024-03-04 00:23:54', '2024-06-09 23:58:04'),
(2, 'A2', '<p><strong><span style=\"font-size:22px\">Course Outcomes:</span></strong></p>\r\n\r\n<p><strong><span style=\"font-size:16px\">After finishing this level, students will be able to:</span></strong></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">write paragraphs with a main idea, supporting details, and a conclusion.</span></li>\r\n	<li><span style=\"font-size:16px\">talk about everyday situations like describing daily routines, a day at work or in school, hobbies etc.</span></li>\r\n	<li><span style=\"font-size:16px\">discuss fairly more complex ideas and objects.</span></li>\r\n	<li><span style=\"font-size:16px\">understand and use words and phrases for everyday situations.</span></li>\r\n	<li><span style=\"font-size:16px\">use major grammar rules like the Degree of Adjectives, Wh-questions, Subject-verb Agreement, and</span></li>\r\n	<li><span style=\"font-size:16px\">Clauses in a basic way.</span></li>\r\n	<li><span style=\"font-size:16px\">listen and understand feelings in speech and find the main points.</span></li>\r\n</ul>\r\n\r\n<ul>\r\n</ul>\r\n\r\n<p><strong><span style=\"font-size:22px\">Course description</span></strong></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Skills Covered:</strong></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Reading, Writing</span></li>\r\n	<li><span style=\"font-size:16px\">Listening, Speaking</span></li>\r\n	<li><span style=\"font-size:16px\">Grammar and Vocabulary</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\"><strong>On-campus class:&nbsp;</strong></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Student Book- 24 hours (Total 16 Classes)</span></li>\r\n	<li><span style=\"font-size:16px\">Language Club- 6 hours</span></li>\r\n	<li><span style=\"font-size:16px\">Assessments- 3 hours</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Online class:</strong></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">A2 Student Book (Listening)- 6 hours</span></li>\r\n	<li><span style=\"font-size:16px\">Total Class and Assessments - 45 hours</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Homework &amp; Assignments:</strong></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Online portal- 60 hours</span></li>\r\n	<li><span style=\"font-size:16px\">HW from Student Book- 15 hours</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Assessment Process:</strong></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Pre-course Assessment Test- 1</span></li>\r\n	<li><span style=\"font-size:16px\">Class test- 16 (2 tests in each 3-hour class)</span></li>\r\n	<li><span style=\"font-size:16px\">Mid-term progress test- 1</span></li>\r\n	<li><span style=\"font-size:16px\">Promotion test (full-length IELTS mock exam)- 1</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Study materials</strong></span></p>\r\n\r\n<ol>\r\n	<li><span style=\"font-size:16px\">A2 Skill Builder, Student Book</span></li>\r\n	<li><span style=\"font-size:16px\">Vocabulary Dairy</span></li>\r\n	<li><span style=\"font-size:16px\">Online Portal</span></li>\r\n</ol>\r\n\r\n<p style=\"text-align:center\"><strong><span style=\"font-size:20px\">Total Duration of Guided Study:&nbsp;&nbsp;120 hours</span></strong></p>', '2024-03-04 02:35:35', '2024-06-10 01:06:59'),
(3, 'B1', '<p><span style=\"font-size:22px\"><strong>Course Outcomes:</strong></span></p>\r\n\r\n<p><strong><span style=\"font-size:16px\">After finishing this level, students will be able to:</span></strong></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">use grammar better when writing your own work.</span></li>\r\n	<li><span style=\"font-size:16px\">write different types of paragraphs, like giving opinions or solving problems, to create longer essays.</span></li>\r\n	<li><span style=\"font-size:16px\">talk comfortably about things like environment, technology, past or current events etc.</span></li>\r\n	<li><span style=\"font-size:16px\">read quickly to find the main ideas in long passages.</span></li>\r\n	<li><span style=\"font-size:16px\">understand complex words by looking at the surrounding text and using synonymous words.</span></li>\r\n	<li><span style=\"font-size:16px\">understand what a speaker is trying to say and summarize their main ideas when listening.</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:22px\"><strong>Course description</strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Skills Covered:</strong></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Reading, Writing,&nbsp;</span></li>\r\n	<li><span style=\"font-size:16px\">Listening, Speaking,&nbsp;</span></li>\r\n	<li><span style=\"font-size:16px\">Grammar and Vocabulary</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\"><strong>On-campus class:&nbsp;</strong></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">B1 Student Book- 30 hours (Total 20 Classes)</span></li>\r\n	<li><span style=\"font-size:16px\">Language Club- 6 hours</span></li>\r\n	<li><span style=\"font-size:16px\">Assessments- 3 hours</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Online class:</strong></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">B1 Student Book (Listening)- 6 hours</span></li>\r\n	<li><span style=\"font-size:16px\">Total Class and Assessments - 45 hours</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Homework &amp;amp; assignments:</strong></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">B1 Practice Book- 60 hours</span></li>\r\n	<li><span style=\"font-size:16px\">HW from Student Book- 15 hours</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Assessment process:</strong></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Pre-course Assessment Test- 1</span></li>\r\n	<li><span style=\"font-size:16px\">Class test- 16 (2 tests in each 3-hour class)</span></li>\r\n	<li><span style=\"font-size:16px\">Mid-term progress test- 1</span></li>\r\n	<li><span style=\"font-size:16px\">Promotion test (full-length IELTS mock exam)- 1</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Study materials</strong></span></p>\r\n\r\n<ol>\r\n	<li><span style=\"font-size:16px\">B1 Skill Builder, Student Book</span></li>\r\n	<li><span style=\"font-size:16px\">B1 Skill Builder, Practice Book</span></li>\r\n	<li><span style=\"font-size:16px\">Vocabulary Dairy</span></li>\r\n</ol>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:20px\"><strong>Total Duration of Guided Study:&nbsp;&nbsp;150 hours</strong></span></p>', '2024-03-04 02:40:44', '2024-06-10 00:37:31'),
(4, 'B2', '<p>&nbsp;</p>\n\n<p><span style=\"font-size:22px\"><strong>Course Outcomes:</strong></span></p>\n\n<p><span style=\"font-size:16px\"><strong>After finishing this level, students will be able to:</strong></span></p>\n\n<ul>\n	<li><span style=\"font-size:16px\">write persuasively using different grammar rules correctly.</span></li>\n	<li><span style=\"font-size:16px\">write academic essays using prompts to make strong arguments.</span></li>\n	<li><span style=\"font-size:16px\">speak easily on topics that frequently appear on IELTS exam.</span></li>\n	<li><span style=\"font-size:16px\">understand and use information from what you read and hear in your own writing.</span></li>\n	<li><span style=\"font-size:16px\">use more advanced words correctly in your writing.</span></li>\n</ul>\n\n<p><span style=\"font-size:22px\"><strong>Course description</strong></span></p>\n\n<p><span style=\"font-size:16px\"><strong>Skills Covered:</strong></span></p>\n\n<ul>\n	<li><span style=\"font-size:16px\">Reading, Writing,</span></li>\n	<li><span style=\"font-size:16px\">Listening, Speaking,</span></li>\n	<li><span style=\"font-size:16px\">Grammar and Vocabulary</span></li>\n</ul>\n\n<p><span style=\"font-size:16px\"><strong>On-campus class:&nbsp;</strong></span></p>\n\n<ul>\n	<li><span style=\"font-size:16px\">Student Book- 30 hours (Total 20 Classes)</span></li>\n	<li><span style=\"font-size:16px\">Language Club- 6 hours</span></li>\n	<li><span style=\"font-size:16px\">Assessments- 5 hours</span></li>\n</ul>\n\n<p><span style=\"font-size:16px\"><strong>Online class:</strong></span></p>\n\n<ul>\n	<li><span style=\"font-size:16px\">B2 Student Book (Listening)- 6 hours</span></li>\n	<li><span style=\"font-size:16px\">Total Class and Assessments - 45 hours</span></li>\n</ul>\n\n<p><span style=\"font-size:16px\"><strong>Homework &amp;amp; assignments:</strong></span></p>\n\n<ul>\n	<li><span style=\"font-size:16px\">B2 Work Book- 60 hours</span></li>\n	<li><span style=\"font-size:16px\">HW from Student Book- 35 hours</span></li>\n</ul>\n\n<p><span style=\"font-size:16px\"><strong>Assessment process:</strong></span></p>\n\n<ul>\n	<li><span style=\"font-size:16px\">Pre-Course Test</span></li>\n	<li><span style=\"font-size:16px\">Class test</span></li>\n	<li><span style=\"font-size:16px\">Mid-term progress test</span></li>\n	<li><span style=\"font-size:16px\">Promotion test (full-length IELTS mock exam)&nbsp;</span></li>\n</ul>\n\n<p><span style=\"font-size:16px\"><strong>Study materials:</strong></span></p>\n\n<ul>\n	<li><span style=\"font-size:16px\">B2 Skill Builder - (Reading &amp;amp; Writing) - Student Book</span></li>\n	<li><span style=\"font-size:16px\">B2 Skill Builder &ndash; (Listening &amp;amp; Speaking) - Student Book</span></li>\n	<li><span style=\"font-size:16px\">B2 Skill Builder - (Reading, Writing, Listening &amp;amp; Speaking) - Work Book</span></li>\n	<li><span style=\"font-size:16px\">Vocabulary Dairy</span></li>\n</ul>\n\n<p style=\"text-align:center\"><span style=\"font-size:20px\"><strong>Total Duration of Guided Study:&nbsp;&nbsp;140 hours</strong></span></p>\n\n<p>&nbsp;</p>', '2024-03-04 02:42:17', '2024-06-10 00:41:25'),
(5, 'C1', '<p><span style=\"font-size:22px\"><strong>Course Outcomes:</strong></span></p>\r\n\r\n<p><strong><span style=\"font-size:16px\">After finishing this level, students will be able to:</span></strong></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">analyze difficult essay topics and write long arguments essays with good command on formal written English</span></li>\r\n	<li><span style=\"font-size:16px\">explain difficult ideas with accuracy and fluency when talking without planning.</span></li>\r\n	<li><span style=\"font-size:16px\">understand and use difficult words with accuracy in all modules of IELTS exam.</span></li>\r\n	<li><span style=\"font-size:16px\">critically read and analyze complex texts on both familiar and unfamiliar topics.</span></li>\r\n</ul>\r\n\r\n<p><strong><span style=\"font-size:22px\">Course description</span></strong></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Skills Covered</strong></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Reading, Writing</span></li>\r\n	<li><span style=\"font-size:16px\">Listening, Speaking</span></li>\r\n	<li><span style=\"font-size:16px\">Grammar and Vocabulary</span></li>\r\n</ul>\r\n\r\n<p><strong><span style=\"font-size:16px\">Total class: &nbsp;&nbsp;&nbsp;&nbsp;15&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<br />\r\nTotal Hours: &nbsp;&nbsp;22.5</span></strong></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Assessment process:</strong></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:16px\">Class test</span></li>\r\n	<li><span style=\"font-size:16px\">Full-length IELTS mock exam</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:16px\">&nbsp;<br />\r\n<strong>Study materials:</strong></span></p>\r\n\r\n<ol>\r\n	<li><span style=\"font-size:16px\">C1 Skill Builder - Student Book- (Reading + Listening)- 01</span></li>\r\n	<li><span style=\"font-size:16px\">C1 Skill Builder - Student Book- (Reading + Listening)- 02</span></li>\r\n	<li><span style=\"font-size:16px\">C1 Skill Builder - Student Book- Writing- 03</span></li>\r\n	<li><span style=\"font-size:16px\">Vocabulary Dairy</span></li>\r\n</ol>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:20px\"><strong>Total Duration of Guided Study:&nbsp;&nbsp;150 hours</strong></span></p>', '2024-03-04 02:43:58', '2024-06-10 00:44:19');
