(10, 1, 10, 'drop-down', '<p><em><strong><span style=\"font-size:20px\">Select the correct sentence from the given options.</span></strong></em></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Identify the mistake (if any) in the following sentence. </span></span></strong></span></span></p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">&quot;<u>When</u> she <u>will come</u>, she <u>will check</u> your <u>homework</u>.&quot;&nbsp;&nbsp; (<strong>No Error: E</strong>)</span></span></span></span></p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><strong><span style=\"font-size:10.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; A&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;B&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;C&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;D</span></span></strong></span></span></p>', '2024-02-27 23:50:59', '2024-07-31 04:58:54'),
(11, 1, 11, 'drop-down', '<p><span style=\"font-size:18px\">Select the meaning of the word within the quotation marks (&lsquo;&rsquo;).</span></p>', '2024-02-27 23:54:32', '2024-07-03 22:56:13');
INSERT INTO `manage_test_questions` (`id`, `test_id`, `section_id`, `question_type`, `instruction`, `created_at`, `updated_at`) VALUES
(12, 1, 12, 'fill-blank', '<p><em><strong><span style=\"font-size:20px\">Complete the sample answer by writing one word from the box in each gap.</span></strong></em></p>\r\n\r\n<p><img src=\"data:image/png;base64,\" style=\"height:354px; width:400px\" /></p>\r\n\r\n<table border=\"1\" cellpadding=\"1\" cellspacing=\"1\" style=\"width:600px\">\r\n	<tbody>\r\n		<tr>\r\n			<td><span style=\"font-size:18px\"><span style=\"color:#000000\">consists</span></span></td>\r\n			<td><span style=\"font-size:18px\"><span style=\"color:#000000\">incidence</span></span></td>\r\n			<td><span style=\"font-size:18px\"><span style=\"color:#000000\">amount&nbsp;</span></span></td>\r\n			<td><span style=\"font-size:18px\"><span style=\"color:#000000\">aspects</span></span></td>\r\n		</tr>\r\n		<tr>\r\n			<td><span style=\"font-size:18px\"><span style=\"color:#000000\">considerably</span></span></td>\r\n			<td><span style=\"font-size:18px\"><span style=\"color:#000000\">similarities</span></span></td>\r\n			<td><span style=\"font-size:18px\"><span style=\"color:#000000\">breakdown</span></span></td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n	</tbody>\r\n</table>', '2024-02-28 00:00:34', '2024-09-10 04:40:39');
INSERT INTO `manage_test_questions` (`id`, `test_id`, `section_id`, `question_type`, `instruction`, `created_at`, `updated_at`) VALUES
(13, 1, 13, 'fill-blank', '<p><span style=\"font-size:20px\"><em><strong>Complete the sample answer by writing one word from the box in each gap.</strong></em></span></p>\r\n\r\n<table border=\"1\" cellpadding=\"1\" cellspacing=\"1\" style=\"width:600px\">\r\n	<tbody>\r\n		<tr>\r\n			<td><span style=\"font-size:16px\">lead</span></td>\r\n			<td><span style=\"font-size:16px\">practicing</span></td>\r\n			<td><span style=\"font-size:16px\">improving</span></td>\r\n			<td><span style=\"font-size:16px\">delaying</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td><span style=\"font-size:16px\">exacerbating</span></td>\r\n			<td><span style=\"font-size:16px\">waste</span></td>\r\n			<td><span style=\"font-size:16px\">manufacture</span></td>\r\n			<td><span style=\"font-size:16px\">consumption</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td><span style=\"font-size:16px\">turnover</span></td>\r\n			<td><span style=\"font-size:16px\">societal</span></td>\r\n			<td><span style=\"font-size:16px\">boost</span></td>\r\n			<td><span style=\"font-size:16px\">booming</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td><span style=\"font-size:16px\">prioritization</span></td>\r\n			<td><span style=\"font-size:16px\">prevalence</span></td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n	</tbody>\r\n</table>', '2024-02-28 00:03:32', '2024-08-28 22:11:06'),
(16, 1, 16, 'fill-blank', '<p><span style=\"font-size:20px\"><em>Questions 1- 5</em></span></p>\r\n\r\n<p><span style=\"font-size:20px\"><em>Complete the sentences below.</em></span></p>\r\n\r\n<p><span style=\"font-size:20px\"><em>Write <strong>NO MORE THAN TWO WORDS AND/OR A NUMBER</strong> for each answer.</em></span></p>', '2024-02-28 00:39:53', '2024-08-13 23:34:34'),
(17, 1, 17, 'multi-selector', '<p><span style=\"font-size:20px\"><em>Questions 6&mdash;8</em></span></p>\r\n\r\n<p><span style=\"font-size:20px\"><em>Choose&nbsp;<strong>THREE</strong> letters A-G.</em></span></p>', '2024-02-28 00:45:19', '2024-08-13 23:45:37'),
(20, 1, 18, 'multiple-choice', '<p><strong><em><span style=\"font-size:20px\">Questions 11 and 15</span></em></strong></p>\r\n\r\n<p><strong><em><span style=\"font-size:20px\">Choose the correct letters A, B or C.</span></em></strong></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:22px\"><strong><em>Research on questions about doctors</em></strong></span></p>', '2024-05-17 00:24:22', '2024-08-14 00:21:39'),
