INSERT INTO `test_drop_downs` (`id`, `test_question_id`, `text`, `option_text`, `is_correct`, `marks`, `created_at`, `updated_at`) VALUES
(1, 2, '4. What kind people need lighthouses?', '[\"-\",\"A) Farmers in fields\",\"B) Airplane pilots\",\"C) Sailors at sea\",\"D) Mountain climbers on cliffs\"]', '[\"3\"]', 1, NULL, NULL),
(2, 2, '5. Which of the following is NOT mentioned in the passage as one of the functions of lighthouses?', '[\"-\",\"A. To help sailors find out their location\",\"B. To warn of danger from rocks and reefs\",\"C. To notify sailors that bad weather is approaching\",\"D. To indicate that land is near\"]', '[\"3\"]', 1, NULL, NULL),
(3, 2, '6. The word ‘hazardous’ in the passage means …', '[\"-\",\"A. High\",\"B. Soft\",\"C. Dangerous\",\"D. Harassing\"]', '[\"3\"]', 1, NULL, NULL),
(7, 11, '1. We should respect the \'adult\' people.', '[\"-\",\"a. younger\",\"b. busy\",\"c. older\"]', '[\"3\"]', 1, NULL, NULL),
(8, 11, '2. Some students find history class \'boring\'.', '[\"-\",\"a. good\",\"b. not interesting\",\"c. difficult\"]', '[\"2\"]', 1, NULL, NULL),
(9, 11, '3. We bought it from the \'local\' market.', '[\"-\",\"a. nearby\",\"b. railway\",\"c. big\"]', '[\"1\"]', 1, NULL, NULL),
(18, 22, '4. How do pets say hello?', '[\"-\",\"a) By singing\",\"b) By wagging their tails\",\"c) By sleeping\"]', '[\"1\"]', 1, NULL, NULL),
(19, 22, '5. What do cats like to do for fun?', '[\"-\",\"a) Go for walks\",\"b) Sleep in the sun\",\"c) Chase cars\"]', '[\"2\"]', 1, NULL, NULL),
(20, 22, '6. What do pets teach us?', '[\"-\",\"a) To be lazy\",\"b) To be responsible\",\"c) To be rude\"]', '[\"2\"]', 1, NULL, NULL),
(21, 26, '1. Cats __________ in the warm sun.', '[\"-\",\"a. sleeping\",\"b. sleep\",\"c. sleeped\"]', '[\"2\"]', 1, NULL, NULL),
(22, 26, '2. Birds sing ____________ in the trees.', '[\"-\",\"a. happier\",\"b. happy\",\"c. happily\"]', '[\"3\"]', 1, NULL, NULL),
(23, 26, '3. I like the story __________.', '[\"-\",\"a. very\",\"b. very much\",\"c. quick march\"]', '[\"2\"]', 1, NULL, NULL),
(24, 29, '10. _________________ initial recognition while still quite young.', '[\"-\",\"(A) Most famous scientists achieve\",\"(B) That most famous scientists achieved\",\"(C) The most famous scientist who achieved\"]', '[\"1\"]', 1, NULL, NULL),
(25, 29, '11. The mountain ____ we climbed yesterday was the highest mountain in Britain!', '[\"-\",\"(A)  where\",\"(B)  which\",\"(C)  what\"]', '[\"2\"]', 1, NULL, NULL),
(26, 29, '12. When I got home, the children had already ___ to bed.', '[\"-\",\"(A)  went\",\"(B)  gone\",\"(C)  going\"]', '[\"2\"]', 1, NULL, NULL),
(33, 44, '1. I __________ to my brother right now.', '[\"-\",\"a. am talking\",\"b. talk\",\"c. talked\"]', '[\"1\"]', 1, NULL, NULL),
(34, 44, '2. __________ to stay home and watch TV.', '[\"-\",\"a. I am going\",\"b. I going\",\"c. Going\"]', '[\"1\"]', 1, NULL, NULL),
(35, 44, '3. My father __________ me a bicycle when I was five years old.', '[\"-\",\"a. buy\",\"b. bought\",\"c. will buy\"]', '[\"2\"]', 1, NULL, NULL),
(36, 48, '13.', '[\"-\",\"a. Dark and threatening, the artist studied the stormy sky.\",\"b. Dark and threatening, the stormy sky studied the artist.\",\"c. The artist studied the stormy sky dark and threatening.\",\"d. The artist studied the dark and threatening stormy sky.\"]', '[\"4\"]', 1, NULL, NULL),
(37, 48, '14.', '[\"-\",\"a. Why don\'t you lodge a complaint for your noisy neighbours?\",\"b. Why don\'t you lodge a complaint against your noisy neighbours?\",\"c. Why don\'t you lodge a complaint about your noisy neighbours?\",\"d. Why don\'t you lodge your noisy neighbours a complaint?\"]', '[\"2\"]', 1, NULL, NULL),
(38, 48, '15.', '[\"-\",\"a. If I had called the president, he probably wouldn\'t speak to me.\",\"b. If I called the president, he probably wouldn\'t have spoken to me.\",\"c. If I had called the president, he probably won\'t speak to me.\",\"d. If I called the president, he probably wouldn\'t speak to me.\"]', '[\"3\"]', 1, NULL, NULL),
(42, 7, '4.Sara’s friends at the college....................that she is always punctual and works very hard.', '[\"-\",\"know\",\"knows\",\"knew\",\"are know\"]', '[\"1\"]', 1, NULL, NULL),
(43, 7, '5. The bouquet of flowers, which were picked from the garden,.....................placed on the table.', '[\"-\",\"are\",\"have been\",\"was\",\"were\"]', '[\"3\"]', 1, NULL, NULL),
(44, 7, '6. Neither the CEO nor the employees......................to take responsibility for the mistake.', '[\"-\",\"want\",\"does want\",\"wants\",\"are want\"]', '[\"1\"]', 1, NULL, NULL),
(45, 10, '12.', '[\"-\",\"A\",\"B\",\"C\",\"D\",\"E\"]', '[\"2\"]', 1, NULL, NULL);
